std::string rle_encode(const std::string& s) {
    if (s.empty()) return "";

    std::vector<std::pair<char, int>> encoded;
    char current_char = s[0];
    int count = 1;

    for (size_t i = 1; i < s.length(); ++i) {
        if (s[i] == current_char) {
            ++count;
        } else {
            encoded.push_back({current_char, count});
            current_char = s[i];
            count = 1;
        }
    }
    encoded.push_back({current_char, count});

    std::string result;
    for (const auto& pair : encoded) {
        result += std::to_string(pair.second) + pair.first;
    }

    return result;
}

