bool balanced(const std::string& s) {
    std::stack<char> stack;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            stack.push(c);
        } else if (c == ')' && !stack.empty() && stack.top() == '(') {
            stack.pop();
        } else if (c == ']' && !stack.empty() && stack.top() == '[') {
            stack.pop();
        } else if (c == '}' && !stack.empty() && stack.top() == '{') {
            stack.pop();
        } else {
            // Ignore other characters
        }
    }
    return stack.empty();
}

