module counter (
    input clk,
    input rst,
    input en,
    output reg [3:0] q
);

    reg [3:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 4'b0000;
        end else if (en) begin
            count <= count + 1'b1;
            if (count == 4'b1111) begin
                count <= 4'b0000;
            end
        end
    end

    assign q = count;

endmodule

module parity8 (
    input [7:0] d,
    output even,
    output odd
);

    // Count the number of 1 bits in the input
    reg [3:0] count;
    always @(d) begin
        count = $countbits(d);
    end

    // Determine the parity
    assign odd = count % 2 == 1;
    assign even = ~odd;

endmodule

module rise_detect (
    input clk,
    input rst,
    input sig,
    output pulse
);

    // Register to hold the current and previous state of sig
    reg [1:0] sig_reg = 2'b00;
    reg [1:0] sig_prev = 2'b00;

    // Pulse signal
    reg pulse_reg = 1'b0;

    // Rising edge detection
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sig_reg <= 2'b00;
            sig_prev <= 2'b00;
            pulse_reg <= 1'b0;
        end else begin
            sig_reg <= sig;
            sig_prev <= sig_reg;
            pulse_reg <= sig_reg & ~sig_prev;
        end
    end

    // Output pulse
    assign pulse = pulse_reg;

endmodule
